1	import { isLeft, isRight } from './input.js';
2	import { resolveX, resolveY } from './level.js';
3	import { addDJParticles, addLandParticles } from './entities.js';
4	import { getJumpMult, getDJMult, getSpeedMult, getEquippedWeapon } from './state.js';
5	
6	function lerp(a, b, t) { return a + (b - a) * t; }
7	
8	const BASE_JUMP = 555;
9	const BASE_DJ = 495;
10	const BASE_SPEED = 280;
11	const GRAVITY = 1850;
12	const TERMINAL_VEL = 950;
13	const COYOTE_TIME = 0.1;
14	// Idle horizontal damping is per-stage now (see STAGE_MODIFIERS `.fric`); base is 0.72.
15	
16	// Per-stage gameplay twist (index 0-9, matches STAGE_THEMES order in renderer.js).
17	//   gMul  — gravity multiplier
18	//   jMul  — jump/double-jump force multiplier (scaled WITH gravity on "heavy"
19	//           stages so required jumps stay reachable — see physics note below)
20	//   fric  — idle horizontal damping per frame (base 0.72; ↑ = slippery, ↓ = grippy)
21	//   wind  — sideways gust acceleration amplitude (px/s², 0 = none)
22	//   dark  — 1 = limited-visibility vignette around the player (rendered in main.js)
23	// NOTE on reachability: scaling gMul and jMul together leaves horizontal jump
24	// distance unchanged and only INCREASES vertical reach, and lowering gMul alone
25	// only increases reach — so every twist keeps all 500 validated levels solvable.
26	export const STAGE_MODIFIERS = [
27	  { label: '🌱 Springy Grass', gMul: 1.0,  jMul: 1.12, fric: 0.72, wind: 0,    dark: 0 }, // Meadow
28	  { label: '🕯️ Pitch Dark',    gMul: 1.0,  jMul: 1.0,  fric: 0.72, wind: 0,    dark: 1 }, // Cave
29	  { label: '❄️ Slippery Ice',  gMul: 1.0,  jMul: 1.0,  fric: 0.965, wind: 0,   dark: 0 }, // Icy Peaks
30	  { label: '🌬️ Desert Gusts',  gMul: 1.0,  jMul: 1.0,  fric: 0.72, wind: 1300, dark: 0 }, // Desert
31	  { label: '🔥 Scorching Heat', gMul: 1.25, jMul: 1.25, fric: 0.72, wind: 0,    dark: 0 }, // Lava
32	  { label: '☁️ Sky Updrafts',  gMul: 0.6,  jMul: 1.0,  fric: 0.78, wind: 0,    dark: 0 }, // Sky
33	  { label: '🍄 Mossy Grip',    gMul: 1.0,  jMul: 1.0,  fric: 0.42, wind: 0,    dark: 0 }, // Forest
34	  { label: '🚀 Zero Gravity',  gMul: 0.32, jMul: 1.0,  fric: 0.86, wind: 0,    dark: 0 }, // Space
35	  { label: '💎 Bouncy Crystal', gMul: 1.0,  jMul: 1.24, fric: 0.72, wind: 0,    dark: 0 }, // Crystal
36	  { label: '🏰 Heavy Gravity',  gMul: 1.45, jMul: 1.45, fric: 0.72, wind: 0,    dark: 0 }, // Dark Fortress
37	];
38	
39	let _mod = STAGE_MODIFIERS[0];
40	let _modT = 0; // time accumulator for oscillating effects (wind gusts)
41	
42	// Select the active stage twist (call before initPlayer on level start/respawn).
43	export function setStageModifier(stageIdx) {
44	  _mod = STAGE_MODIFIERS[((stageIdx % 10) + 10) % 10] || STAGE_MODIFIERS[0];
45	  _modT = 0;
46	}
47	
48	export function getStageModifier() { return _mod; }
49	
50	export const player = {
51	  x: 80, y: 380,
52	  w: 28, h: 42,
53	  vx: 0, vy: 0,
54	  _prevY: 380,
55	  onGround: false,
56	  jumpsLeft: 2,
57	  coyoteTimer: 0,
58	  jumpBufferTimer: 0,
59	  facing: 1,
60	  distanceTraveled: 0,
61	  animState: 'idle',
62	  animTimer: 0,
63	  landSquash: 0,
64	  djFlash: 0,
65	  dead: false,
66	  // Health
67	  maxHp: 100,
68	  hp: 100,
69	  invuln: 0,          // i-frame timer after taking a hit (no further contact damage)
70	  hurtFlash: 0,       // red flash timer when damaged
71	  // Combat
72	  attackCD: 0,        // seconds until the next attack is allowed
73	  swingT: 0,          // remaining swing-animation time
74	  swingDur: 0.16,
75	  weapon: null,       // equipped weapon def (for drawing)
76	  // Computed from upgrades each level
77	  jumpForce: BASE_JUMP,
78	  djForce: BASE_DJ,
79	  speed: BASE_SPEED,
80	};
81	
82	export function initPlayer(spawnX, spawnY) {
83	  player.x = spawnX;
84	  player.y = spawnY;
85	  player._prevY = spawnY - 1; // slightly above to trigger landing on first frame
86	  player.vx = 0;
87	  player.vy = 0;
88	  player.onGround = false;
89	  player.jumpsLeft = 2;
90	  player.coyoteTimer = COYOTE_TIME;
91	  player.jumpBufferTimer = 0;
92	  player.facing = 1;
93	  player.distanceTraveled = 0;
94	  player.animState = 'idle';
95	  player.animTimer = 0;
96	  player.landSquash = 0;
97	  player.djFlash = 0;
98	  player.dead = false;
99	  player.maxHp = 100;
100	  player.hp = 100;
101	  player.invuln = 0;
102	  player.hurtFlash = 0;
103	  player.attackCD = 0;
104	  player.swingT = 0;
105	  player.weapon = getEquippedWeapon();
106	
107	  player.jumpForce = BASE_JUMP * getJumpMult() * _mod.jMul;
108	  player.djForce = BASE_DJ * getDJMult() * _mod.jMul;
109	  player.speed = BASE_SPEED * getSpeedMult();
110	}
111	
112	export function updatePlayer(dt, platforms, jumpJustPressed) {
113	  if (player.dead) return;
114	
115	  // Ride moving platforms: if grounded on one last frame, inherit its motion
116	  // this frame so the player stays attached instead of sliding off.
117	  if (player.onGround && player._groundPlat && player._groundPlat.type === 'move') {
118	    player.x += player._groundPlat._dx || 0;
119	    player.y += player._groundPlat._dy || 0;
120	  }
121	
122	  // Jump buffer
123	  if (jumpJustPressed) player.jumpBufferTimer = 0.085;
124	  else if (player.jumpBufferTimer > 0) player.jumpBufferTimer = Math.max(0, player.jumpBufferTimer - dt);
125	
126	  // Coyote timer decrement
127	  if (!player.onGround) {
128	    player.coyoteTimer = Math.max(0, player.coyoteTimer - dt);
129	  }
130	
131	  // Jump logic
132	  if (player.jumpBufferTimer > 0) {
133	    if (player.coyoteTimer > 0 && player.jumpsLeft === 2) {
134	      // Ground / coyote jump
135	      player.vy = -player.jumpForce;
136	      player.coyoteTimer = 0;
137	      player.jumpBufferTimer = 0;
138	      player.jumpsLeft = 1; // first jump used
139	      player.animState = 'jump';
140	    } else if (player.jumpsLeft > 0 && player.coyoteTimer <= 0) {
141	      // Double jump
142	      player.vy = -player.djForce;
143	      player.jumpsLeft = 0;
144	      player.jumpBufferTimer = 0;
145	      player.djFlash = 0.28;
146	      player.animState = 'jump';
147	      addDJParticles(player.x + player.w / 2, player.y + player.h);
148	    }
149	  }
150	
151	  _modT += dt;
152	
153	  // Horizontal movement (idle damping varies by stage: slippery ice vs. mossy grip)
154	  const targetVx = isLeft() ? -player.speed : isRight() ? player.speed : 0;
155	  if (targetVx !== 0) {
156	    player.vx = targetVx;
157	    player.facing = targetVx > 0 ? 1 : -1;
158	  } else {
159	    player.vx *= _mod.fric;
160	    if (Math.abs(player.vx) < 8) player.vx = 0;
161	  }
162	
163	  // Desert gusts: oscillating sideways push you must lean against.
164	  if (_mod.wind) player.vx += _mod.wind * Math.sin(_modT * 0.6) * dt;
165	
166	  // Gravity (per-stage multiplier; terminal velocity tracks it so low-g feels floaty)
167	  const grav = GRAVITY * _mod.gMul;
168	  const term = TERMINAL_VEL * Math.max(0.45, _mod.gMul);
169	  player.vy = Math.min(player.vy + grav * dt, term);
170	
171	  // Store prevY for collision resolution
172	  player._prevY = player.y;
173	
174	  // Move X → resolve X (uses current y, before y-move)
175	  player.x += player.vx * dt;
176	  player.x = Math.max(0, player.x); // left wall clamp
177	  resolveX(player, platforms);
178	
179	  // Move Y → resolve Y (uses _prevY to determine landing direction)
180	  player._prevY = player.y;
181	  player.y += player.vy * dt;
182	
183	  const wasOnGround = player.onGround;
184	  player.onGround = resolveY(player, platforms);
185	
186	  if (player.onGround) {
187	    player.jumpsLeft = 2;
188	    player.coyoteTimer = COYOTE_TIME;
189	    if (!wasOnGround) {
190	      // Just landed
191	      player.landSquash = 0.18;
192	      addLandParticles(player.x + player.w / 2, player.y + player.h);
193	    }
194	  }
195	
196	  // Update timers
197	  player.landSquash = Math.max(0, player.landSquash - dt * 5.5);
198	  player.djFlash = Math.max(0, player.djFlash - dt);
199	  player.attackCD = Math.max(0, player.attackCD - dt);
200	  player.swingT = Math.max(0, player.swingT - dt);
201	  player.invuln = Math.max(0, player.invuln - dt);
202	  player.hurtFlash = Math.max(0, player.hurtFlash - dt);
203	
204	  // Walk distance for leg swing animation
205	  if (player.onGround && Math.abs(player.vx) > 15) {
206	    player.distanceTraveled += Math.abs(player.vx) * dt;
207	  }
208	
209	  // Animation state
210	  if (!player.onGround) {
211	    player.animState = player.vy > 80 ? 'fall' : 'jump';
212	  } else if (Math.abs(player.vx) > 15) {
213	    player.animState = 'walk';
214	  } else {
215	    player.animState = 'idle';
216	  }
217	
218	  player.animTimer += dt;
219	}
220	
221	export function drawPlayer(ctx, t) {
222	  const { x, y, w, h, facing, animState, animTimer, landSquash, djFlash, distanceTraveled } = player;
223	
224	  const centerX = x + w / 2;
225	  const centerY = y + h / 2;
226	
227	  ctx.save();
228	  ctx.translate(centerX, centerY);
229	  if (facing < 0) ctx.scale(-1, 1);
230	
231	  // Blink while invulnerable (i-frames) so the player can read that hits won't land.
232	  if (player.invuln > 0) ctx.globalAlpha = 0.4 + 0.6 * Math.abs(Math.sin(player.invuln * 30));
233	
234	  // Squash/stretch transform
235	  let sx = 1, sy = 1;
236	  if (landSquash > 0) {
237	    const n = landSquash / 0.18;
238	    sx = 1 + 0.42 * n;
239	    sy = 1 - 0.38 * n;
240	  } else if (animState === 'jump') {
241	    sx = 0.82; sy = 1.22;
242	  } else if (animState === 'fall') {
243	    sx = 1.12; sy = 0.83;
244	  } else if (animState === 'idle') {
245	    sy = 1 + Math.sin(animTimer * 3.2) * 0.028;
246	  }
247	  ctx.scale(sx, sy);
248	
249	  const hw = w / 2;
250	  const hh = h / 2;
251	
252	  // --- Legs ---
253	  const legSwing = animState === 'walk' ? Math.sin(distanceTraveled * 0.048) * 0.55 : 0;
254	  drawLimb(ctx, -hw * 0.38, hh * 0.25, legSwing, '#1a252f', 6, hh * 0.48);
255	  drawLimb(ctx, hw * 0.38, hh * 0.25, -legSwing, '#1a252f', 6, hh * 0.48);
256	
257	  // --- Body (shirt) ---
258	  ctx.fillStyle = '#2980b9';
259	  roundRect(ctx, -hw * 0.72, -hh * 0.22, w * 0.72, h * 0.52, 5);
260	  ctx.fill();
261	  // Shirt detail (stripe)
262	  ctx.fillStyle = '#1a6fa8';
263	  ctx.fillRect(-hw * 0.72, hh * 0.06, w * 0.72, 4);
264	
265	  // --- Arms ---
266	  const armSwing = animState === 'walk' ? -legSwing * 0.85 : 0;
267	  const armFall = animState === 'fall' ? 0.75 : 0;
268	  drawLimb(ctx, hw * 0.72, -hh * 0.1, armFall + armSwing, '#f0a070', 5, hh * 0.38, true);
269	  drawLimb(ctx, -hw * 0.72, -hh * 0.1, armFall - armSwing, '#f0a070', 5, hh * 0.38, true);
270	
271	  // --- Head ---
272	  ctx.fillStyle = '#f5cba7';
273	  ctx.beginPath();
274	  ctx.arc(0, -hh * 0.42, hw * 0.85, 0, Math.PI * 2);
275	  ctx.fill();
276	
277	  // Ear
278	  ctx.fillStyle = '#e8b898';
279	  ctx.beginPath();
280	  ctx.arc(hw * 0.78, -hh * 0.38, 4, 0, Math.PI * 2);
281	  ctx.fill();
282	
283	  // Hair
284	  ctx.fillStyle = '#5d4037';
285	  ctx.beginPath();
286	  ctx.arc(-hw * 0.08, -hh * 0.78, 7.5, 0, Math.PI * 2);
287	  ctx.arc(hw * 0.18, -hh * 0.82, 6.5, 0, Math.PI * 2);
288	  ctx.arc(hw * 0.5, -hh * 0.75, 5.5, 0, Math.PI * 2);
289	  ctx.fill();
290	  // Hair band
291	  ctx.strokeStyle = '#3e2723';
292	  ctx.lineWidth = 2;
293	  ctx.beginPath();
294	  ctx.arc(0, -hh * 0.42, hw * 0.8, Math.PI * 1.1, Math.PI * 1.9);
295	  ctx.stroke();
296	
297	  // Eyes (right eye is front when facing right)
298	  const eyeY = -hh * 0.42;
299	  // Whites
300	  ctx.fillStyle = 'white';
301	  ctx.beginPath();
302	  ctx.ellipse(hw * 0.28, eyeY, 5, 5.5, 0, 0, Math.PI * 2);
303	  ctx.ellipse(-hw * 0.12, eyeY, 4, 4.5, 0, 0, Math.PI * 2);
304	  ctx.fill();
305	  // Pupils
306	  ctx.fillStyle = '#1a1a2e';
307	  ctx.beginPath();
308	  ctx.arc(hw * 0.34, eyeY, 2.5, 0, Math.PI * 2);
309	  ctx.arc(-hw * 0.08, eyeY, 2, 0, Math.PI * 2);
310	  ctx.fill();
311	  // Eye shine
312	  ctx.fillStyle = 'white';
313	  ctx.beginPath();
314	  ctx.arc(hw * 0.38, eyeY - 1.5, 1, 0, Math.PI * 2);
315	  ctx.arc(-hw * 0.05, eyeY - 1.5, 0.9, 0, Math.PI * 2);
316	  ctx.fill();
317	
318	  // Smile
319	  ctx.strokeStyle = '#c0624a';
320	  ctx.lineWidth = 1.5;
321	  ctx.beginPath();
322	  ctx.arc(hw * 0.1, eyeY + 9, 5, 0.1, Math.PI - 0.1);
323	  ctx.stroke();
324	
325	  // Weapon swing / attack
326	  if (player.swingT > 0 && player.weapon) {
327	    drawWeaponSwing(ctx, hw, hh, player.weapon, 1 - player.swingT / player.swingDur);
328	  }
329	
330	  // Hurt flash — red tint over the body when damaged
331	  if (player.hurtFlash > 0) {
332	    ctx.globalAlpha = (player.hurtFlash / 0.3) * 0.6;
333	    ctx.fillStyle = '#ff2b2b';
334	    roundRect(ctx, -hw, -hh, w, h, 6);
335	    ctx.fill();
336	    ctx.globalAlpha = 1;
337	  }
338	
339	  // Double-jump flash outline
340	  if (djFlash > 0) {
341	    const flashAlpha = djFlash / 0.28;
342	    ctx.strokeStyle = `rgba(0,255,229,${flashAlpha})`;
343	    ctx.lineWidth = 3;
344	    ctx.beginPath();
345	    ctx.arc(0, -hh * 0.1, hw * 1.35, 0, Math.PI * 2);
346	    ctx.stroke();
347	    ctx.lineWidth = 1;
348	  }
349	
350	  ctx.restore();
351	}
352	
353	// Draws the equipped weapon mid-swing in front of the player. Called inside the
354	// player's translated+facing-flipped context, so +x is always "forward".
355	function drawWeaponSwing(ctx, hw, hh, weapon, prog) {
356	  ctx.save();
357	  ctx.translate(hw * 0.55, -hh * 0.05); // shoulder pivot
358	
359	  if (weapon.type === 'ranged') {
360	    // Hold the weapon level and forward, with a muzzle flash early in the swing.
361	    ctx.fillStyle = '#2a2a33';
362	    ctx.fillRect(0, -3.5, 18, 7);
363	    ctx.fillStyle = weapon.color;
364	    ctx.fillRect(15, -2.5, 7, 5);
365	    if (prog < 0.55) {
366	      ctx.globalAlpha = 1 - prog / 0.55;
367	      ctx.fillStyle = weapon.color;
368	      ctx.beginPath();
369	      ctx.arc(26, 0, 7, 0, Math.PI * 2);
370	      ctx.fill();
371	      ctx.globalAlpha = 1;
372	    }
373	    ctx.restore();
374	    return;
375	  }
376	
377	  // Melee: arc the arm + weapon from overhead down through forward.
378	  const reach = weapon.reach || 26;
379	  const ang = lerp(-1.0, 1.05, prog);
380	  ctx.rotate(ang);
381	
382	  // swoosh trail
383	  ctx.strokeStyle = 'rgba(255,255,255,0.35)';
384	  ctx.lineWidth = 2.5;
385	  ctx.beginPath();
386	  ctx.arc(0, 0, reach * 0.85, -0.55, 0.55);
387	  ctx.stroke();
388	
389	  // arm
390	  ctx.strokeStyle = '#f0a070';
391	  ctx.lineWidth = 5;
392	  ctx.lineCap = 'round';
393	  ctx.beginPath();
394	  ctx.moveTo(0, 0);
395	  ctx.lineTo(reach * 0.45, 0);
396	  ctx.stroke();
397	
398	  ctx.translate(reach * 0.45, 0);
399	  if (weapon.key === 'fists') {
400	    ctx.fillStyle = weapon.color;
401	    ctx.beginPath();
402	    ctx.arc(4, 0, 6.5, 0, Math.PI * 2);
403	    ctx.fill();
404	  } else if (weapon.key === 'hammer') {
405	    ctx.fillStyle = '#5a4632';
406	    ctx.fillRect(0, -2.5, reach * 0.45, 5);
407	    ctx.fillStyle = weapon.color;
408	    ctx.fillRect(reach * 0.45 - 3, -9, 13, 18);
409	  } else {
410	    // sword (and any other blade)
411	    ctx.fillStyle = '#8a8a96';
412	    ctx.fillRect(-3, -5, 5, 10); // guard
413	    ctx.fillStyle = weapon.color;
414	    ctx.fillRect(2, -2.5, reach * 0.75, 5); // blade
415	  }
416	  ctx.restore();
417	}
418	
419	function drawLimb(ctx, x, y, angle, color, w, length, isArm = false) {
420	  ctx.save();
421	  ctx.translate(x, y);
422	  ctx.rotate(angle);
423	  ctx.fillStyle = color;
424	  if (isArm) {
425	    ctx.fillRect(0, -w / 2, length, w);
426	  } else {
427	    ctx.fillRect(-w / 2, 0, w, length);
428	    // Shoe
429	    ctx.fillStyle = '#212121';
430	    ctx.fillRect(-w / 2 - 1, length - 5, w + 4, 7);
431	  }
432	  ctx.restore();
433	}
434	
435	function roundRect(ctx, x, y, w, h, r) {
436	  ctx.beginPath();
437	  ctx.moveTo(x + r, y);
438	  ctx.lineTo(x + w - r, y);
439	  ctx.arcTo(x + w, y, x + w, y + r, r);
440	  ctx.lineTo(x + w, y + h - r);
441	  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
442	  ctx.lineTo(x + r, y + h);
443	  ctx.arcTo(x, y + h, x, y + h - r, r);
444	  ctx.lineTo(x, y + r);
445	  ctx.arcTo(x, y, x + r, y, r);
446	  ctx.closePath();
447	}
