import { isLeft, isRight } from './input.js';
import { resolveX, resolveY } from './level.js';
import { addDJParticles, addLandParticles } from './entities.js';
import { getJumpMult, getDJMult, getSpeedMult, getEquippedWeapon } from './state.js';

function lerp(a, b, t) { return a + (b - a) * t; }

const BASE_JUMP = 555;
const BASE_DJ = 495;
const BASE_SPEED = 280;
const GRAVITY = 1850;
const TERMINAL_VEL = 950;
const COYOTE_TIME = 0.1;
// Idle horizontal damping is per-stage now (see STAGE_MODIFIERS `.fric`); base is 0.72.

// Per-stage gameplay twist (index 0-9, matches STAGE_THEMES order in renderer.js).
//   gMul  — gravity multiplier
//   jMul  — jump/double-jump force multiplier (scaled WITH gravity on "heavy"
//           stages so required jumps stay reachable — see physics note below)
//   fric  — idle horizontal damping per frame (base 0.72; ↑ = slippery, ↓ = grippy)
//   wind  — sideways gust acceleration amplitude (px/s², 0 = none)
//   dark  — 1 = limited-visibility vignette around the player (rendered in main.js)
// NOTE on reachability: scaling gMul and jMul together leaves horizontal jump
// distance unchanged and only INCREASES vertical reach, and lowering gMul alone
// only increases reach — so every twist keeps all 500 validated levels solvable.
export const STAGE_MODIFIERS = [
  { label: '🌱 Springy Grass', gMul: 1.0,  jMul: 1.12, fric: 0.72, wind: 0,    dark: 0 }, // Meadow
  { label: '🕯️ Pitch Dark',    gMul: 1.0,  jMul: 1.0,  fric: 0.72, wind: 0,    dark: 1 }, // Cave
  { label: '❄️ Slippery Ice',  gMul: 1.0,  jMul: 1.0,  fric: 0.965, wind: 0,   dark: 0 }, // Icy Peaks
  { label: '🌬️ Desert Gusts',  gMul: 1.0,  jMul: 1.0,  fric: 0.72, wind: 1300, dark: 0 }, // Desert
  { label: '🔥 Scorching Heat', gMul: 1.25, jMul: 1.25, fric: 0.72, wind: 0,    dark: 0 }, // Lava
  { label: '☁️ Sky Updrafts',  gMul: 0.6,  jMul: 1.0,  fric: 0.78, wind: 0,    dark: 0 }, // Sky
  { label: '🍄 Mossy Grip',    gMul: 1.0,  jMul: 1.0,  fric: 0.42, wind: 0,    dark: 0 }, // Forest
  { label: '🚀 Zero Gravity',  gMul: 0.32, jMul: 1.0,  fric: 0.86, wind: 0,    dark: 0 }, // Space
  { label: '💎 Bouncy Crystal', gMul: 1.0,  jMul: 1.24, fric: 0.72, wind: 0,    dark: 0 }, // Crystal
  { label: '🏰 Heavy Gravity',  gMul: 1.45, jMul: 1.45, fric: 0.72, wind: 0,    dark: 0 }, // Dark Fortress
];

let _mod = STAGE_MODIFIERS[0];
let _modT = 0; // time accumulator for oscillating effects (wind gusts)

// Select the active stage twist (call before initPlayer on level start/respawn).
export function setStageModifier(stageIdx) {
  _mod = STAGE_MODIFIERS[((stageIdx % 10) + 10) % 10] || STAGE_MODIFIERS[0];
  _modT = 0;
}

export function getStageModifier() { return _mod; }

export const player = {
  x: 80, y: 380,
  w: 28, h: 42,
  vx: 0, vy: 0,
  _prevY: 380,
  onGround: false,
  jumpsLeft: 2,
  coyoteTimer: 0,
  jumpBufferTimer: 0,
  facing: 1,
  distanceTraveled: 0,
  animState: 'idle',
  animTimer: 0,
  landSquash: 0,
  djFlash: 0,
  dead: false,
  // Health
  maxHp: 100,
  hp: 100,
  invuln: 0,          // i-frame timer after taking a hit (no further contact damage)
  hurtFlash: 0,       // red flash timer when damaged
  // Combat
  attackCD: 0,        // seconds until the next attack is allowed
  swingT: 0,          // remaining swing-animation time
  swingDur: 0.16,
  weapon: null,       // equipped weapon def (for drawing)
  // Computed from upgrades each level
  jumpForce: BASE_JUMP,
  djForce: BASE_DJ,
  speed: BASE_SPEED,
};

export function initPlayer(spawnX, spawnY) {
  player.x = spawnX;
  player.y = spawnY;
  player._prevY = spawnY - 1; // slightly above to trigger landing on first frame
  player.vx = 0;
  player.vy = 0;
  player.onGround = false;
  player.jumpsLeft = 2;
  player.coyoteTimer = COYOTE_TIME;
  player.jumpBufferTimer = 0;
  player.facing = 1;
  player.distanceTraveled = 0;
  player.animState = 'idle';
  player.animTimer = 0;
  player.landSquash = 0;
  player.djFlash = 0;
  player.dead = false;
  player.maxHp = 100;
  player.hp = 100;
  player.invuln = 0;
  player.hurtFlash = 0;
  player.attackCD = 0;
  player.swingT = 0;
  player.weapon = getEquippedWeapon();

  player.jumpForce = BASE_JUMP * getJumpMult() * _mod.jMul;
  player.djForce = BASE_DJ * getDJMult() * _mod.jMul;
  player.speed = BASE_SPEED * getSpeedMult();
}

export function updatePlayer(dt, platforms, jumpJustPressed) {
  if (player.dead) return;

  // Ride moving platforms: if grounded on one last frame, inherit its motion
  // this frame so the player stays attached instead of sliding off.
  if (player.onGround && player._groundPlat && player._groundPlat.type === 'move') {
    player.x += player._groundPlat._dx || 0;
    player.y += player._groundPlat._dy || 0;
  }

  // Jump buffer
  if (jumpJustPressed) player.jumpBufferTimer = 0.085;
  else if (player.jumpBufferTimer > 0) player.jumpBufferTimer = Math.max(0, player.jumpBufferTimer - dt);

  // Coyote timer decrement
  if (!player.onGround) {
    player.coyoteTimer = Math.max(0, player.coyoteTimer - dt);
  }

  // Jump logic
  if (player.jumpBufferTimer > 0) {
    if (player.coyoteTimer > 0 && player.jumpsLeft === 2) {
      // Ground / coyote jump
      player.vy = -player.jumpForce;
      player.coyoteTimer = 0;
      player.jumpBufferTimer = 0;
      player.jumpsLeft = 1; // first jump used
      player.animState = 'jump';
    } else if (player.jumpsLeft > 0 && player.coyoteTimer <= 0) {
      // Double jump
      player.vy = -player.djForce;
      player.jumpsLeft = 0;
      player.jumpBufferTimer = 0;
      player.djFlash = 0.28;
      player.animState = 'jump';
      addDJParticles(player.x + player.w / 2, player.y + player.h);
    }
  }

  _modT += dt;

  // Horizontal movement (idle damping varies by stage: slippery ice vs. mossy grip)
  const targetVx = isLeft() ? -player.speed : isRight() ? player.speed : 0;
  if (targetVx !== 0) {
    player.vx = targetVx;
    player.facing = targetVx > 0 ? 1 : -1;
  } else {
    player.vx *= _mod.fric;
    if (Math.abs(player.vx) < 8) player.vx = 0;
  }

  // Desert gusts: oscillating sideways push you must lean against.
  if (_mod.wind) player.vx += _mod.wind * Math.sin(_modT * 0.6) * dt;

  // Gravity (per-stage multiplier; terminal velocity tracks it so low-g feels floaty)
  const grav = GRAVITY * _mod.gMul;
  const term = TERMINAL_VEL * Math.max(0.45, _mod.gMul);
  player.vy = Math.min(player.vy + grav * dt, term);

  // Store prevY for collision resolution
  player._prevY = player.y;

  // Move X → resolve X (uses current y, before y-move)
  player.x += player.vx * dt;
  player.x = Math.max(0, player.x); // left wall clamp
  resolveX(player, platforms);

  // Move Y → resolve Y (uses _prevY to determine landing direction)
  player._prevY = player.y;
  player.y += player.vy * dt;

  const wasOnGround = player.onGround;
  player.onGround = resolveY(player, platforms);

  if (player.onGround) {
    player.jumpsLeft = 2;
    player.coyoteTimer = COYOTE_TIME;
    if (!wasOnGround) {
      // Just landed
      player.landSquash = 0.18;
      addLandParticles(player.x + player.w / 2, player.y + player.h);
    }
  }

  // Update timers
  player.landSquash = Math.max(0, player.landSquash - dt * 5.5);
  player.djFlash = Math.max(0, player.djFlash - dt);
  player.attackCD = Math.max(0, player.attackCD - dt);
  player.swingT = Math.max(0, player.swingT - dt);
  player.invuln = Math.max(0, player.invuln - dt);
  player.hurtFlash = Math.max(0, player.hurtFlash - dt);

  // Walk distance for leg swing animation
  if (player.onGround && Math.abs(player.vx) > 15) {
    player.distanceTraveled += Math.abs(player.vx) * dt;
  }

  // Animation state
  if (!player.onGround) {
    player.animState = player.vy > 80 ? 'fall' : 'jump';
  } else if (Math.abs(player.vx) > 15) {
    player.animState = 'walk';
  } else {
    player.animState = 'idle';
  }

  player.animTimer += dt;
}

export function drawPlayer(ctx, t) {
  const { x, y, w, h, facing, animState, animTimer, landSquash, djFlash, distanceTraveled } = player;

  const centerX = x + w / 2;
  const centerY = y + h / 2;

  ctx.save();
  ctx.translate(centerX, centerY);
  if (facing < 0) ctx.scale(-1, 1);

  // Blink while invulnerable (i-frames) so the player can read that hits won't land.
  if (player.invuln > 0) ctx.globalAlpha = 0.4 + 0.6 * Math.abs(Math.sin(player.invuln * 30));

  // Squash/stretch transform
  let sx = 1, sy = 1;
  if (landSquash > 0) {
    const n = landSquash / 0.18;
    sx = 1 + 0.42 * n;
    sy = 1 - 0.38 * n;
  } else if (animState === 'jump') {
    sx = 0.82; sy = 1.22;
  } else if (animState === 'fall') {
    sx = 1.12; sy = 0.83;
  } else if (animState === 'idle') {
    sy = 1 + Math.sin(animTimer * 3.2) * 0.028;
  }
  ctx.scale(sx, sy);

  const hw = w / 2;
  const hh = h / 2;

  // --- Legs ---
  const legSwing = animState === 'walk' ? Math.sin(distanceTraveled * 0.048) * 0.55 : 0;
  drawLimb(ctx, -hw * 0.38, hh * 0.25, legSwing, '#1a252f', 6, hh * 0.48);
  drawLimb(ctx, hw * 0.38, hh * 0.25, -legSwing, '#1a252f', 6, hh * 0.48);

  // --- Body (shirt) ---
  ctx.fillStyle = '#2980b9';
  roundRect(ctx, -hw * 0.72, -hh * 0.22, w * 0.72, h * 0.52, 5);
  ctx.fill();
  // Shirt detail (stripe)
  ctx.fillStyle = '#1a6fa8';
  ctx.fillRect(-hw * 0.72, hh * 0.06, w * 0.72, 4);

  // --- Arms ---
  const armSwing = animState === 'walk' ? -legSwing * 0.85 : 0;
  const armFall = animState === 'fall' ? 0.75 : 0;
  drawLimb(ctx, hw * 0.72, -hh * 0.1, armFall + armSwing, '#f0a070', 5, hh * 0.38, true);
  drawLimb(ctx, -hw * 0.72, -hh * 0.1, armFall - armSwing, '#f0a070', 5, hh * 0.38, true);

  // --- Head ---
  ctx.fillStyle = '#f5cba7';
  ctx.beginPath();
  ctx.arc(0, -hh * 0.42, hw * 0.85, 0, Math.PI * 2);
  ctx.fill();

  // Ear
  ctx.fillStyle = '#e8b898';
  ctx.beginPath();
  ctx.arc(hw * 0.78, -hh * 0.38, 4, 0, Math.PI * 2);
  ctx.fill();

  // Hair
  ctx.fillStyle = '#5d4037';
  ctx.beginPath();
  ctx.arc(-hw * 0.08, -hh * 0.78, 7.5, 0, Math.PI * 2);
  ctx.arc(hw * 0.18, -hh * 0.82, 6.5, 0, Math.PI * 2);
  ctx.arc(hw * 0.5, -hh * 0.75, 5.5, 0, Math.PI * 2);
  ctx.fill();
  // Hair band
  ctx.strokeStyle = '#3e2723';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(0, -hh * 0.42, hw * 0.8, Math.PI * 1.1, Math.PI * 1.9);
  ctx.stroke();

  // Eyes (right eye is front when facing right)
  const eyeY = -hh * 0.42;
  // Whites
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.ellipse(hw * 0.28, eyeY, 5, 5.5, 0, 0, Math.PI * 2);
  ctx.ellipse(-hw * 0.12, eyeY, 4, 4.5, 0, 0, Math.PI * 2);
  ctx.fill();
  // Pupils
  ctx.fillStyle = '#1a1a2e';
  ctx.beginPath();
  ctx.arc(hw * 0.34, eyeY, 2.5, 0, Math.PI * 2);
  ctx.arc(-hw * 0.08, eyeY, 2, 0, Math.PI * 2);
  ctx.fill();
  // Eye shine
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(hw * 0.38, eyeY - 1.5, 1, 0, Math.PI * 2);
  ctx.arc(-hw * 0.05, eyeY - 1.5, 0.9, 0, Math.PI * 2);
  ctx.fill();

  // Smile
  ctx.strokeStyle = '#c0624a';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(hw * 0.1, eyeY + 9, 5, 0.1, Math.PI - 0.1);
  ctx.stroke();

  // Weapon swing / attack
  if (player.swingT > 0 && player.weapon) {
    drawWeaponSwing(ctx, hw, hh, player.weapon, 1 - player.swingT / player.swingDur);
  }

  // Hurt flash — red tint over the body when damaged
  if (player.hurtFlash > 0) {
    ctx.globalAlpha = (player.hurtFlash / 0.3) * 0.6;
    ctx.fillStyle = '#ff2b2b';
    roundRect(ctx, -hw, -hh, w, h, 6);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  // Double-jump flash outline
  if (djFlash > 0) {
    const flashAlpha = djFlash / 0.28;
    ctx.strokeStyle = `rgba(0,255,229,${flashAlpha})`;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, -hh * 0.1, hw * 1.35, 0, Math.PI * 2);
    ctx.stroke();
    ctx.lineWidth = 1;
  }

  ctx.restore();
}

// Draws the equipped weapon mid-swing in front of the player. Called inside the
// player's translated+facing-flipped context, so +x is always "forward".
function drawWeaponSwing(ctx, hw, hh, weapon, prog) {
  ctx.save();
  ctx.translate(hw * 0.55, -hh * 0.05); // shoulder pivot

  if (weapon.type === 'ranged') {
    // Hold the weapon level and forward, with a muzzle flash early in the swing.
    ctx.fillStyle = '#2a2a33';
    ctx.fillRect(0, -3.5, 18, 7);
    ctx.fillStyle = weapon.color;
    ctx.fillRect(15, -2.5, 7, 5);
    if (prog < 0.55) {
      ctx.globalAlpha = 1 - prog / 0.55;
      ctx.fillStyle = weapon.color;
      ctx.beginPath();
      ctx.arc(26, 0, 7, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();
    return;
  }

  // Melee: arc the arm + weapon from overhead down through forward.
  const reach = weapon.reach || 26;
  const ang = lerp(-1.0, 1.05, prog);
  ctx.rotate(ang);

  // swoosh trail
  ctx.strokeStyle = 'rgba(255,255,255,0.35)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.arc(0, 0, reach * 0.85, -0.55, 0.55);
  ctx.stroke();

  // arm
  ctx.strokeStyle = '#f0a070';
  ctx.lineWidth = 5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(reach * 0.45, 0);
  ctx.stroke();

  ctx.translate(reach * 0.45, 0);
  if (weapon.key === 'fists') {
    ctx.fillStyle = weapon.color;
    ctx.beginPath();
    ctx.arc(4, 0, 6.5, 0, Math.PI * 2);
    ctx.fill();
  } else if (weapon.key === 'hammer') {
    ctx.fillStyle = '#5a4632';
    ctx.fillRect(0, -2.5, reach * 0.45, 5);
    ctx.fillStyle = weapon.color;
    ctx.fillRect(reach * 0.45 - 3, -9, 13, 18);
  } else {
    // sword (and any other blade)
    ctx.fillStyle = '#8a8a96';
    ctx.fillRect(-3, -5, 5, 10); // guard
    ctx.fillStyle = weapon.color;
    ctx.fillRect(2, -2.5, reach * 0.75, 5); // blade
  }
  ctx.restore();
}

function drawLimb(ctx, x, y, angle, color, w, length, isArm = false) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.fillStyle = color;
  if (isArm) {
    ctx.fillRect(0, -w / 2, length, w);
  } else {
    ctx.fillRect(-w / 2, 0, w, length);
    // Shoe
    ctx.fillStyle = '#212121';
    ctx.fillRect(-w / 2 - 1, length - 5, w + 4, 7);
  }
  ctx.restore();
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h - r);
  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.lineTo(x + r, y + h);
  ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

import { getTheme } from './renderer.js';

function mulberry32(seed) {
  let s = seed >>> 0;
  return function () {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(s ^ (s >>> 15), s | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const GW = 800;
export const GH = 500;
export const GROUND_Y = 430;

// Vertical bounds for placing standable surfaces.
const TOP = 80;            // ceiling clearance
const FLOOR = GROUND_Y - 20; // 410 — comfortable baseline platform top
// Most you can climb in a single jump (keeps every required leap reachable).
const MAX_RISE = 95;

// Crumble timing (seconds): how long after you land before it drops, and
// how long until it regenerates so retries stay possible.
const CRUMBLE_DELAY = 0.42;
const CRUMBLE_REGEN = 2.8;

function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

// ─── PER-STAGE CHARACTER ─────────────────────────────────────────────────────
// Each biome plays differently, not just recolored:
//   grounded — lay a continuous floor so a missed jump lands on terrain instead
//              of an endless death-void (fields, cave floor, desert, forest).
//   low      — keep platforms near that floor as rolling terrain (paired w/ grounded).
//   pool     — which segments may appear (by id). Terrain stages get hills/spikes;
//              floating stages also get the moving/crumbling "vehicle" segments.
//   flyerFreq — how common the stage's air species are (cave bats, sky birds…).
//   (Enemy species themselves live in SPECIES / STAGE_ROSTER below.)
const TERRAIN_POOL = ['gap', 'stairsUp', 'stairsDown', 'coinVault', 'pillars',
  'zigzag', 'longLeap', 'descent', 'spikePath', 'spikeLeap', 'gauntlet'];

const STAGE_PROFILES = [
  { grounded: true,  low: true,  pool: TERRAIN_POOL, flyerFreq: 1.0 }, // 0 Meadow — grassy field
  { grounded: true,  low: true,  pool: TERRAIN_POOL, flyerFreq: 1.7 }, // 1 Cave — stalagmites + bats
  { grounded: false, low: false, pool: null,         flyerFreq: 0.5 }, // 2 Icy Peaks — floating & slippery
  { grounded: true,  low: true,  pool: TERRAIN_POOL, flyerFreq: 1.0 }, // 3 Desert — dunes & cacti
  { grounded: false, low: false, pool: null,         flyerFreq: 0.9 }, // 4 Lava — islands over magma
  { grounded: false, low: false, pool: null,         flyerFreq: 1.9 }, // 5 Sky — birds everywhere
  { grounded: true,  low: true,  pool: TERRAIN_POOL, flyerFreq: 0.9 }, // 6 Forest — woodland floor
  { grounded: false, low: false, pool: null,         flyerFreq: 1.7 }, // 7 Space — drones & turrets
  { grounded: false, low: false, pool: null,         flyerFreq: 1.0 }, // 8 Crystal — shards over abyss
  { grounded: false, low: false, pool: null,         flyerFreq: 1.2 }, // 9 Dark Fortress — ramparts
];
function getProfile(stageIdx) { return STAGE_PROFILES[((stageIdx % 10) + 10) % 10] || STAGE_PROFILES[0]; }

// ─── ENEMY SPECIES ───────────────────────────────────────────────────────────
// Every stage fields its own bespoke species with DIFFERENT BEHAVIOR, not a
// reskin. behavior ∈ walk / hop / charge / fly / swoop / float / orbit / drop /
// spider / shoot — implemented in entities.js `updateEnemies`, drawn per-species
// in `drawEnemies`. `air` foes skip knockback clamping; `color` tints particles.
const SPECIES = {
  slime:    p => ({ species: 'slime',    behavior: 'hop',    w: 26, h: 20, hp: 1 + Math.floor(p * 2), dmg: 5,  color: '#58b94a', speed: lerp(28, 55, p), jumpForce: lerp(230, 300, p), jumpEvery: lerp(1.2, 0.8, p) }),
  bee:      p => ({ species: 'bee',      behavior: 'fly',    air: true, w: 24, h: 20, hp: 1, dmg: 4, color: '#f9ca24', chase: 80 }),
  crawler:  p => ({ species: 'crawler',  behavior: 'walk',   w: 30, h: 20, hp: 2 + Math.floor(p * 2), dmg: 6,  color: '#7f8c8d', speed: lerp(35, 70, p) }),
  bat:      p => ({ species: 'bat',      behavior: 'swoop',  air: true, w: 30, h: 22, hp: 1 + Math.floor(p * 2), dmg: 6, color: '#786fa6', swoopRange: 170, swoopSpeed: lerp(230, 310, p) }),
  slider:   p => ({ species: 'slider',   behavior: 'walk',   w: 30, h: 24, hp: 2 + Math.floor(p * 2), dmg: 7,  color: '#82ccdd', speed: lerp(100, 160, p) }),
  icicle:   p => ({ species: 'icicle',   behavior: 'drop',   air: true, w: 18, h: 30, hp: 1, dmg: 12, color: '#aee3ff' }),
  scorpion: p => ({ species: 'scorpion', behavior: 'charge', w: 34, h: 20, hp: 2 + Math.floor(p * 3), dmg: 8,  color: '#cc8e35', speed: lerp(30, 55, p), chargeRange: 180, chargeSpeed: lerp(260, 340, p) }),
  vulture:  p => ({ species: 'vulture',  behavior: 'orbit',  air: true, w: 34, h: 24, hp: 1 + Math.floor(p * 2), dmg: 6, color: '#935116', orbitR: lerp(50, 85, p), orbitSpd: lerp(1.5, 2.2, p) }),
  lavablob: p => ({ species: 'lavablob', behavior: 'hop',    w: 30, h: 24, hp: 2 + Math.floor(p * 3), dmg: 9,  color: '#ff793f', speed: lerp(38, 66, p), jumpForce: lerp(420, 520, p), jumpEvery: 0.15 }),
  ember:    p => ({ species: 'ember',    behavior: 'fly',    air: true, w: 20, h: 24, hp: 1, dmg: 5, color: '#ffb142', chase: 95 }),
  bird:     p => ({ species: 'bird',     behavior: 'swoop',  air: true, w: 34, h: 24, hp: 1 + Math.floor(p * 2), dmg: 6, color: '#f5f6fa', swoopRange: 210, swoopSpeed: lerp(270, 350, p) }),
  puff:     p => ({ species: 'puff',     behavior: 'float',  air: true, w: 30, h: 24, hp: 1 + Math.floor(p * 2), dmg: 5, color: '#dfe6e9', floatSpeed: lerp(42, 70, p) }),
  spider:   p => ({ species: 'spider',   behavior: 'spider', air: true, w: 26, h: 20, hp: 1 + Math.floor(p * 2), dmg: 7, color: '#8d6e4a', dropSpeed: 330 }),
  shroom:   p => ({ species: 'shroom',   behavior: 'hop',    w: 26, h: 24, hp: 2 + Math.floor(p * 2), dmg: 6, color: '#e17055', speed: lerp(24, 48, p), jumpForce: lerp(380, 460, p), jumpEvery: lerp(1.7, 1.1, p) }),
  drone:    p => ({ species: 'drone',    behavior: 'orbit',  air: true, w: 28, h: 18, hp: 2 + Math.floor(p * 2), dmg: 6, color: '#00d2d3', orbitR: lerp(45, 75, p), orbitSpd: lerp(2.1, 2.9, p) }),
  turret:   p => ({ species: 'turret',   behavior: 'shoot',  w: 30, h: 22, hp: 3 + Math.floor(p * 3), dmg: 8, color: '#4834d4', shotDmg: 8, range: 430, fireEvery: lerp(2.6, 1.9, p) }),
  golem:    p => ({ species: 'golem',    behavior: 'walk',   w: 42, h: 38, hp: 6 + Math.floor(p * 6), dmg: 12, color: '#48dbfb', speed: lerp(20, 42, p) }),
  shard:    p => ({ species: 'shard',    behavior: 'orbit',  air: true, w: 22, h: 26, hp: 1 + Math.floor(p * 2), dmg: 7, color: '#00ffe5', orbitR: lerp(55, 90, p), orbitSpd: lerp(1.8, 2.6, p) }),
  knight:   p => ({ species: 'knight',   behavior: 'charge', w: 32, h: 34, hp: 5 + Math.floor(p * 6), dmg: 12, color: '#8854d0', speed: lerp(24, 44, p), chargeRange: 210, chargeSpeed: lerp(300, 380, p) }),
  wraith:   p => ({ species: 'wraith',   behavior: 'float',  air: true, w: 30, h: 32, hp: 2 + Math.floor(p * 3), dmg: 8, color: '#9b59b6', floatSpeed: lerp(50, 85, p) }),
};

// What each stage fields: ground patrollers, air dwellers (placed over gaps),
// and hang species (anchored above walkways — falling icicles, web spiders).
const STAGE_ROSTER = [
  { ground: [['slime', 1]],    air: [['bee', 1]],                 hang: [] },              // 0 Meadow
  { ground: [['crawler', 1]],  air: [['bat', 1]],                 hang: [] },              // 1 Cave
  { ground: [['slider', 1]],   air: [],                           hang: [['icicle', 1]] }, // 2 Icy Peaks
  { ground: [['scorpion', 1]], air: [['vulture', 1]],             hang: [] },              // 3 Desert
  { ground: [['lavablob', 1]], air: [['ember', 1]],               hang: [] },              // 4 Lava
  { ground: [],                air: [['bird', 1], ['puff', 0.7]], hang: [] },              // 5 Sky
  { ground: [['shroom', 1]],   air: [],                           hang: [['spider', 1]] }, // 6 Forest
  { ground: [['turret', 1]],   air: [['drone', 1]],               hang: [] },              // 7 Space
  { ground: [['golem', 1]],    air: [['shard', 1]],               hang: [] },              // 8 Crystal
  { ground: [['knight', 1]],   air: [['wraith', 1]],              hang: [] },              // 9 Dark Fortress
];

