100	function pickSpecies(list, rng) {
101	  let total = 0;
102	  for (const s of list) total += s[1];
103	  let r = rng() * total;
104	  for (const s of list) { r -= s[1]; if (r <= 0) return s[0]; }
105	  return list[0][0];
106	}
107	
108	// ─── BOSSES ──────────────────────────────────────────────────────────────────
109	// Every 10th level fields the stage's signature species scaled up ×3 on a huge
110	// arena. Ground bosses use the 'boss' leap-chase behavior; sky/space bosses are
111	// giant swoopers. The exit is locked until the boss dies.
112	const BOSS_SPECIES = ['slime', 'crawler', 'slider', 'scorpion', 'lavablob',
113	  'bird', 'shroom', 'drone', 'golem', 'knight'];
114	
115	function makeBoss(stageIdx, p, arena) {
116	  const sp = BOSS_SPECIES[((stageIdx % 10) + 10) % 10];
117	  const base = SPECIES[sp](p);
118	  const scale = 3;
119	  const w = base.w * scale, h = base.h * scale;
120	  const flying = sp === 'bird' || sp === 'drone';
121	  const e = {
122	    ...base, boss: true, bossScale: scale, w, h,
123	    hp: 24 + Math.round(p * 36), dmg: Math.max(14, (base.dmg || 8) + 8),
124	    x: Math.round(arena.x + arena.w * 0.6), dir: -1, phase: 0,
125	    patrolMin: arena.x + 6, patrolMax: arena.x + arena.w - 6 - w,
126	  };
127	  if (flying) {
128	    e.behavior = 'swoop'; e.air = true;
129	    e.baseX = Math.round(arena.x + arena.w / 2);
130	    e.baseY = Math.max(TOP + 50, arena.y - 215);
131	    e.y = e.baseY;
132	    e.swoopRange = 560; e.swoopSpeed = 300 + p * 90;
133	  } else {
134	    e.behavior = 'boss'; e.air = false;
135	    e.y = arena.y - h;
136	    e.baseY = arena.y - h;
137	    e.speed = 60 + p * 60;
138	    e.leapForce = 660; e.leapEvery = Math.max(1.3, 2.3 - p);
139	  }
140	  // Per-species special attack cooldowns
141	  const SP_CD = { slime: 4.0, crawler: 5.0, slider: 3.5, scorpion: 4.2, lavablob: 3.0,
142	                  bird: 4.0, shroom: 4.5, drone: 3.8, golem: 5.5, knight: 4.0 };
143	  e._baseCD = SP_CD[sp] || 4.0;
144	  e._specialCD = e._baseCD * 0.45; // first special fires sooner so players see it quickly
145	  return e;
146	}
