148	function mkP(x, y, w, type = 'normal') {
149	  return { x: Math.round(x), y: Math.round(y), w: Math.max(40, Math.round(w)), h: 20, type };
150	}
151	function mkGround(x, w) {
152	  return { x: Math.round(x), y: GROUND_Y, w: Math.max(1, Math.round(w)), h: GH - GROUND_Y, type: 'ground' };
153	}
154	function mkCoin(x, y, spin) {
155	  return { x: Math.round(x), y: Math.round(y), collected: false, spinAngle: spin };
156	}
157	
158	function nCoins(coins, plat, n, rng) {
159	  const sp = plat.w / (n + 1);
160	  for (let c = 0; c < n; c++) {
161	    coins.push(mkCoin(plat.x + sp * (c + 1) - 8, plat.y - 36, rng() * Math.PI * 2));
162	  }
163	}
