function movingPos(m, t) {
  const osc = Math.sin(t * m.speed) * 0.5 + 0.5; // 0..1, eases at the ends
  if (m.axis === 'x') return { x: m.baseX + osc * (m.max - m.baseX), y: m.baseY };
  return { x: m.baseX, y: m.baseY + osc * (m.max - m.baseY) };
}

